<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import api from '@/api'
import { dateTime } from '@/utils/format'

const active=ref('categories');const categories=ref([]);const banners=ref([]);const announcements=ref([]);const dialog=ref(false);const dialogType=ref('category');const editing=ref(null)
const categoryForm=reactive({name:'',icon:'Box',color:'#2f7d32',sort_order:0,enabled:true});const bannerForm=reactive({title:'',subtitle:'',image:'/assets/hero-campus.png',link:'/market',sort_order:0,enabled:true});const noticeForm=reactive({title:'',content:'',announcement_type:'notice',pinned:false,enabled:true})
const load=async()=>{[categories.value,banners.value,announcements.value]=await Promise.all([api.get('/admin/categories'),api.get('/admin/banners'),api.get('/admin/announcements')])}
const open=(type,row=null)=>{dialogType.value=type;editing.value=row;const form=type==='category'?categoryForm:type==='banner'?bannerForm:noticeForm;const defaults=type==='category'?{name:'',icon:'Box',color:'#2f7d32',sort_order:0,enabled:true}:type==='banner'?{title:'',subtitle:'',image:'/assets/hero-campus.png',link:'/market',sort_order:0,enabled:true}:{title:'',content:'',announcement_type:'notice',pinned:false,enabled:true};Object.assign(form,defaults,row||{});dialog.value=true}
const save=async()=>{if(dialogType.value==='category'){editing.value?await api.put(`/admin/categories/${editing.value.id}`,categoryForm):await api.post('/admin/categories',categoryForm)}else if(dialogType.value==='banner'){editing.value?await api.put(`/admin/banners/${editing.value.id}`,bannerForm):await api.post('/admin/banners',bannerForm)}else{await api.post('/admin/announcements',noticeForm)}ElMessage.success('运营内容已保存');dialog.value=false;load()}
onMounted(load)
</script>
<template><div><div class="operation-tabs"><button v-for="item in [{v:'categories',l:'商品分类',i:'Menu'},{v:'banners',l:'首页轮播',i:'Picture'},{v:'announcements',l:'公告管理',i:'Notification'}]" :key="item.v" :class="{active:active===item.v}" @click="active=item.v"><el-icon><component :is="item.i"/></el-icon>{{item.l}}</button></div><section class="admin-card"><div class="admin-card-header"><div><h2>{{{categories:'商品分类',banners:'首页轮播',announcements:'平台公告'}[active]}}</h2><p>{{{categories:'维护前台分类入口和排序',banners:'配置首页活动内容和跳转',announcements:'发布交易安全与运营通知'}[active]}}</p></div><el-button type="success" @click="open(active==='categories'?'category':active==='banners'?'banner':'notice')"><el-icon><Plus/></el-icon>新增{{active==='categories'?'分类':active==='banners'?'轮播':'公告'}}</el-button></div><el-table v-if="active==='categories'" :data="categories"><el-table-column label="排序" prop="sort_order" width="80"/><el-table-column label="分类"><template #default="{row}"><div class="category-cell"><span :style="{color:row.color,backgroundColor:`${row.color}15`}"><el-icon><component :is="row.icon"/></el-icon></span><strong>{{row.name}}</strong></div></template></el-table-column><el-table-column label="图标" prop="icon"/><el-table-column label="商品数量" prop="product_count"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button size="small" @click="open('category',row)">编辑</el-button></template></el-table-column></el-table><el-table v-else-if="active==='banners'" :data="banners"><el-table-column label="预览" width="150"><template #default="{row}"><img class="banner-thumb" :src="row.image"/></template></el-table-column><el-table-column label="标题" min-width="220"><template #default="{row}"><strong>{{row.title}}</strong><small class="block">{{row.subtitle}}</small></template></el-table-column><el-table-column label="跳转" prop="link"/><el-table-column label="排序" prop="sort_order"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'展示中':'已停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button size="small" @click="open('banner',row)">编辑</el-button></template></el-table-column></el-table><el-table v-else :data="announcements"><el-table-column label="标题" min-width="250"><template #default="{row}"><strong>{{row.title}}</strong><el-tag v-if="row.pinned" class="pin" size="small" type="warning">置顶</el-tag></template></el-table-column><el-table-column label="类型"><template #default="{row}">{{{notice:'平台通知',safety:'安全提醒',campaign:'运营活动'}[row.announcement_type]||row.announcement_type}}</template></el-table-column><el-table-column label="内容" min-width="350" show-overflow-tooltip prop="content"/><el-table-column label="发布时间" width="160"><template #default="{row}">{{dateTime(row.published_at)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'已发布':'草稿'}}</el-tag></template></el-table-column></el-table></section><el-dialog v-model="dialog" :title="`${editing?'编辑':'新增'}${dialogType==='category'?'分类':dialogType==='banner'?'轮播':'公告'}`" width="540px"><el-form v-if="dialogType==='category'" label-position="top"><el-form-item label="分类名称"><el-input v-model="categoryForm.name"/></el-form-item><div class="form-row"><el-form-item label="Element Plus 图标名"><el-input v-model="categoryForm.icon"/></el-form-item><el-form-item label="主题颜色"><el-color-picker v-model="categoryForm.color"/></el-form-item><el-form-item label="排序"><el-input-number v-model="categoryForm.sort_order" :min="0"/></el-form-item></div><el-switch v-model="categoryForm.enabled" active-text="启用分类"/></el-form><el-form v-else-if="dialogType==='banner'" label-position="top"><el-form-item label="主标题"><el-input v-model="bannerForm.title"/></el-form-item><el-form-item label="副标题"><el-input v-model="bannerForm.subtitle"/></el-form-item><el-form-item label="图片地址"><el-input v-model="bannerForm.image"/></el-form-item><div class="form-row"><el-form-item label="跳转地址"><el-input v-model="bannerForm.link"/></el-form-item><el-form-item label="排序"><el-input-number v-model="bannerForm.sort_order" :min="0"/></el-form-item></div><el-switch v-model="bannerForm.enabled" active-text="启用轮播"/></el-form><el-form v-else label-position="top"><el-form-item label="公告标题"><el-input v-model="noticeForm.title"/></el-form-item><el-form-item label="公告类型"><el-select v-model="noticeForm.announcement_type" style="width:100%"><el-option label="平台通知" value="notice"/><el-option label="安全提醒" value="safety"/><el-option label="运营活动" value="campaign"/></el-select></el-form-item><el-form-item label="公告内容"><el-input v-model="noticeForm.content" type="textarea" :rows="5"/></el-form-item><div class="switch-row"><el-switch v-model="noticeForm.pinned" active-text="置顶公告"/><el-switch v-model="noticeForm.enabled" active-text="立即发布"/></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="success" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped>.operation-tabs{display:flex;gap:8px;margin-bottom:16px}.operation-tabs button{height:43px;display:flex;align-items:center;gap:7px;padding:0 18px;border:1px solid #dde4dd;border-radius:8px;background:#fff;color:#617068}.operation-tabs button.active{border-color:#28773d;background:#eaf3e8;color:#246f39;font-weight:700}.admin-card-header p{margin-top:5px;color:#8c958e;font-size:11px}.category-cell{display:flex;align-items:center;gap:10px}.category-cell span{width:35px;height:35px;display:grid;place-items:center;border-radius:8px}.banner-thumb{width:120px;height:60px;object-fit:cover;border-radius:6px}.block{display:block;max-width:330px;margin-top:5px;overflow:hidden;color:#8e9790;font-size:10px;white-space:nowrap;text-overflow:ellipsis}.pin{margin-left:8px}.form-row{display:grid;grid-template-columns:1fr 100px 110px;gap:12px}.switch-row{display:flex;gap:25px}</style>

